(function(root){'use strict';
const core=typeof module!=='undefined'&&module.exports?require('./booking-core.js'):root.GulplajBooking;
function monthDays(year,month){return new Date(Date.UTC(year,month+1,0)).getUTCDate();}
function iso(year,month,day){return new Date(Date.UTC(year,month,day)).toISOString().slice(0,10);}
function shiftMonth(value,delta){const d=new Date(core.parseDate(value));const first=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+delta,1));return iso(first.getUTCFullYear(),first.getUTCMonth(),Math.min(d.getUTCDate(),monthDays(first.getUTCFullYear(),first.getUTCMonth())));}
function monthGrid(year,month){const first=new Date(Date.UTC(year,month,1));return {offset:(first.getUTCDay()+6)%7,dates:Array.from({length:monthDays(year,month)},(_,i)=>iso(year,month,i+1))};}
if(typeof module!=='undefined'&&module.exports){module.exports={monthGrid,shiftMonth};return;}
const $=s=>document.querySelector(s),dialog=$('#date-calendar'),grid=$('#calendar-days'),title=$('#calendar-month');let activeInput,trigger,focused,year,month;
const inputs=[$('#checkin'),$('#checkout')];
function minimum(input){const today=core.hotelToday();return input.id==='checkout'?core.addDays($('#checkin').value>=today?$('#checkin').value:today,1):today;}
function sync(){inputs.forEach(input=>{$('#'+input.id+'-trigger .date-value').textContent=core.displayDate(input.value)||'Tarih seçin';});}
function render(focus=false){const min=minimum(activeInput);const model=monthGrid(year,month);title.textContent=new Intl.DateTimeFormat('tr-TR',{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(Date.UTC(year,month,1)));grid.replaceChildren();for(let i=0;i<model.offset;i++){const blank=document.createElement('span');blank.setAttribute('aria-hidden','true');grid.append(blank);}model.dates.forEach((date,i)=>{const b=document.createElement('button');b.type='button';b.className='calendar-day';b.textContent=String(i+1);b.dataset.date=date;b.disabled=date<min;b.tabIndex=date===focused?0:-1;b.setAttribute('aria-label',core.displayDate(date));if(date===activeInput.value){b.classList.add('selected');b.setAttribute('aria-pressed','true');}if(date===core.hotelToday())b.setAttribute('aria-current','date');b.addEventListener('click',()=>{activeInput.value=date;activeInput.dispatchEvent(new Event('change',{bubbles:true}));sync();dialog.close();});grid.append(b);});const first=iso(year,month,1);$('#calendar-prev').disabled=first.slice(0,7)<=min.slice(0,7);$('#calendar-next').disabled=year>=2200&&month===11;if(!grid.querySelector('[tabindex="0"]')){const b=grid.querySelector('button:not(:disabled)');if(b){b.tabIndex=0;focused=b.dataset.date;}}if(focus)grid.querySelector('[tabindex="0"]')?.focus();}
function open(input){activeInput=input;trigger=$('#'+input.id+'-trigger');const min=minimum(input);focused=core.parseDate(input.value)!==null&&input.value>=min?input.value:min;const d=new Date(core.parseDate(focused));year=d.getUTCFullYear();month=d.getUTCMonth();$('#calendar-title').textContent=input.id==='checkin'?'Giriş tarihini seçin':'Çıkış tarihini seçin';render();dialog.showModal();trigger.setAttribute('aria-expanded','true');grid.querySelector('[tabindex="0"]')?.focus();}
inputs.forEach(input=>$('#'+input.id+'-trigger').addEventListener('click',()=>open(input)));
$('#calendar-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{trigger?.setAttribute('aria-expanded','false');trigger?.focus();});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
function navigate(delta){focused=shiftMonth(focused,delta);const min=minimum(activeInput);if(focused<min)focused=min;const d=new Date(core.parseDate(focused));year=d.getUTCFullYear();month=d.getUTCMonth();render(true);}
$('#calendar-prev').addEventListener('click',()=>navigate(-1));$('#calendar-next').addEventListener('click',()=>navigate(1));
grid.addEventListener('keydown',e=>{const b=e.target.closest('[data-date]');if(!b)return;const d=new Date(core.parseDate(b.dataset.date)),weekday=(d.getUTCDay()+6)%7;let delta;if(e.key==='ArrowRight')delta=1;if(e.key==='ArrowLeft')delta=-1;if(e.key==='ArrowDown')delta=7;if(e.key==='ArrowUp')delta=-7;if(e.key==='Home')delta=-weekday;if(e.key==='End')delta=6-weekday;if(e.key==='PageUp'||e.key==='PageDown'){e.preventDefault();navigate(e.key==='PageUp'?-1:1);return;}if(delta!==undefined){e.preventDefault();let target=core.addDays(b.dataset.date,delta);if(target<minimum(activeInput))target=minimum(activeInput);if(core.parseDate(target)===null)return;focused=target;const date=new Date(core.parseDate(target));year=date.getUTCFullYear();month=date.getUTCMonth();render(true);}});
$('#booking-form').addEventListener('change',sync);sync();
})(typeof window!=='undefined'?window:globalThis);
